#!/bin/bash
# Prints the judge logins ONCE to your terminal for you to paste into the submission. The passwords live only in Secret Manager
# (generated by deploy.sh); this reads them with YOUR credentials. Nothing is written to disk. Re-running prints them again, so
# restrict who holds secretmanager.secretAccessor on the project.
here=$(cd "$(dirname "$0")" && pwd)
# shellcheck disable=SC1091
. "$here/lib.sh"; need_project
get() { gcloud secrets versions access latest --secret "$SC_PREFIX-$1" --project "$GCP_PROJECT"; }
echo "URL: https://$(public_host)/"
printf '%-14s %-20s %s\n' ROLE USERNAME PASSWORD
printf '%-14s %-20s %s\n' coordinator  maryam.alsuwaidi "$(get pw-coordinator)"
printf '%-14s %-20s %s\n' clinician    huda.rahman      "$(get pw-clinician)"
printf '%-14s %-20s %s\n' supervisor   noura.alhammadi  "$(get pw-supervisor)"
printf '%-14s %-20s %s\n' patient      demo.patient     "$(get pw-patient)"
echo "(also available: layla.haddad / karim.nasser / lab.intake; get them with: gcloud secrets versions access latest --secret sc-demo-pw-owner|pw-specialist|pw-lab)"
echo "These are demo logins for SYNTHETIC data. Delete the deployment after judging (teardown.sh)."
